WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_age_d_reverse'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '由年龄差反推年龄', 'kp-age-d-reverse', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "由年龄差反推年龄"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心推论：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "年龄差 = 差份数。知道差几岁，知道差几倍，瞬间就能知道具体几岁。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“甲乙年龄相差 15 岁，今年甲是乙的 4 倍。求甲多大？”"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心法则"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "甲是乙的 4 倍，说明甲占 4 份，乙占 1 份。他们之间差了 3 份。"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "这 3 份，正好等于年龄差 15 岁！所以 1 份 = 5 岁。甲(4份) = 20岁。秒杀！"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[提取两人的倍数比 a:b] --> B[算出份数差 |a-b|]\nB --> C[找到两人的固定年龄差 Δ]\nC --> D[Δ ÷ 份数差 = 1 份对应的真实年龄]\nD --> E[乘回各自的份数得出真实年龄]"}}]}$$ AS jsonb), NULL, '由年龄差反推年龄的核心考点与实战推导。', category_node.id, CAST('["数量关系", "年龄问题", "由年龄差反推年龄"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_age_d_reverse", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
